ee:message.ee:set-payload:
%dw 2.0
output application/json
var cause = [
    {
      "origin": "remedy-sapi-services",
      "message": vars.remedy_resp.Envelope.Body.Get_CustomerResponse.Get_CustomerResult.WSResponseHeader.service.statusDetail default ""
    }
] ++  ((vars.salesforce_resp default []) map ((item, index) -> 
        {
            "origin": "salesforce-sapi-services",
            "message": item.message default ""
        }
    ))
---
{
  "status": 409,
  "code": "INTERNAL_SERVER_ERROR",
  "message": {
    "message": ""
  },
  "messageServer": cause reduce ((i, acc = "") -> 
    if(acc == "") i.message else if(i.message != "") acc ++ " | " ++ i.message else acc
  ),
  "cause": cause
}

%dw 2.0
output application/json
---
{
  "status": 404,
  "code": "NOT_FOUND",
  "message": {
    "message": ""
  },
  "messageServer": "No se encontraron datos",
  "cause": [
    {
      "origin": "salesforce-sapi-services",
      "message": ""
    },
    {
      "origin": "remedy-sapi-services",
      "message": vars.remedy_resp.Envelope.Body.Get_CustomerResponse.Get_CustomerResult.WSResponseHeader.service.statusDetail default ""
    }
  ]
}
